import { createContext } from 'react';

import type { FilterFieldReducerAction } from '../state/filter-field-state-reducer.js';
import type { _FilterFieldSuggestionMode } from '../suggestions/Suggestion.js';

export interface FilterFieldContextProps {
  applySuggestion: (value: string, mode: _FilterFieldSuggestionMode) => void;
  dispatch: React.Dispatch<FilterFieldReducerAction>;
  focusedSuggestion?: string;
  filterFieldId?: string;
  term?: string;
  autoSuggestions: {
    showComparisonOperatorSuggestions?: boolean;
    showLogicalOperatorSuggestions?: boolean;
    showValueSuggestions?: boolean;
    trailing?: string;
  };
}

export const FilterFieldContext = createContext<FilterFieldContextProps>({
  applySuggestion: () => null,
  dispatch: () => null,
  autoSuggestions: {},
});
